// Generated by tooling/unicode-cases/regexp.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, The design and Staying identical to node.
// Context: a non-ASCII code point folds into ASCII only in Unicode-aware matching.
const pattern0 = /^k$/i;
const pattern1 = /^k$/iu;
const pattern2 = /^k$/iv;
const samples: [string, boolean, boolean, boolean][] = [
  ["\u004b", true, true, true],
  ["\u006b", true, true, true],
  ["\u212a", false, true, true],
  ["\u212b", false, false, false],
  ["\u004b\u004b", false, false, false],
];
for (const sample of samples) {
  assert.sameValue(pattern0.test(sample[0]), sample[1], "kelvin-simple-fold pattern 0");
  assert.sameValue(pattern1.test(sample[0]), sample[2], "kelvin-simple-fold pattern 1");
  assert.sameValue(pattern2.test(sample[0]), sample[3], "kelvin-simple-fold pattern 2");
}
